"""Integrity regressions use generated bytes, never private Apple media."""

from pathlib import Path
from types import SimpleNamespace

import pytest
from photointel.config import Settings
from photointel.errors import AppError
from photointel.services.download_cache import (
    cache_binding,
    complete_download,
    completed_cache_valid,
    marker_path,
    partial_offset,
    write_partial_marker,
)
from photointel.services.ingestion import ICloudAdapter, classify_icloud_failure


def test_equal_size_corruption_is_not_a_valid_completed_cache(tmp_path: Path) -> None:
    target = tmp_path / "revision-a.image"
    partial = target.with_suffix(".part")
    partial.write_bytes(b"correct-media")
    version = SimpleNamespace(size=13, checksum="opaque-source-value")
    binding = cache_binding(version, target)
    complete_download(partial, target, binding)
    assert completed_cache_valid(target, binding)
    target.write_bytes(b"corrupt-media")
    assert target.stat().st_size == version.size
    assert not completed_cache_valid(target, binding)
    assert "opaque-source-value" not in marker_path(target).read_text()


def test_partial_requires_matching_representation_and_completion_marker(
    tmp_path: Path,
) -> None:
    target = tmp_path / "revision-a.image"
    partial = target.with_suffix(".part")
    partial.write_bytes(b"incomplete")
    binding = cache_binding(SimpleNamespace(size=20, checksum="a"), target)
    assert partial_offset(partial, binding) == 0
    write_partial_marker(partial, binding)
    assert partial_offset(partial, binding) == len(b"incomplete")
    changed = cache_binding(SimpleNamespace(size=20, checksum="b"), target)
    assert partial_offset(partial, changed) == 0


def test_download_replaces_equal_size_corrupt_cache_and_then_reuses_it(
    tmp_path: Path,
) -> None:
    target = tmp_path / "revision.image"
    payload = b"valid-image-payload"
    target.write_bytes(b"x" * len(payload))
    calls = []

    class Response:
        status_code = 200
        headers = {"Content-Length": str(len(payload))}

        def raise_for_status(self):
            pass

        def iter_content(self, chunk_size):
            yield payload

        def close(self):
            pass

    def download(*args, **kwargs):
        calls.append(kwargs)
        return Response()

    adapter = ICloudAdapter(Settings(max_download_bytes=1024))
    adapter.client = SimpleNamespace(session=object())
    version = SimpleNamespace(size=len(payload), checksum="opaque", url="not-logged")
    photo = SimpleNamespace(download=download)
    assert adapter.download(photo, version, target) == len(payload)
    assert target.read_bytes() == payload
    assert adapter.download(photo, version, target) == 0
    assert len(calls) == 1
    target.write_bytes(b"z" * len(payload))
    assert adapter.download(photo, version, target) == len(payload)
    assert len(calls) == 2


def test_cache_marker_cannot_authorize_different_revision(tmp_path: Path) -> None:
    target = tmp_path / "revision-a.image"
    partial = target.with_suffix(".part")
    partial.write_bytes(b"abc")
    binding = cache_binding(SimpleNamespace(size=3, checksum="source"), target)
    complete_download(partial, target, binding)
    changed = cache_binding(
        SimpleNamespace(size=3, checksum="source"), tmp_path / "revision-b.image"
    )
    assert not completed_cache_valid(target, changed)


def test_installed_sdk_has_verified_photoasset_constructor() -> None:
    pytest.importorskip("pyicloud_ipd")
    from pyicloud_ipd.services.photos import PhotoAsset

    asset = PhotoAsset({"recordName": "downloader-only-id"}, {})
    assert asset.id == "downloader-only-id"
    assert not hasattr(asset, "cloudIdentifier")


def test_equal_size_partial_corruption_invalidates_resume(tmp_path: Path) -> None:
    partial = tmp_path / "revision.part"
    partial.write_bytes(b"correct")
    binding = cache_binding(SimpleNamespace(size=20, checksum="a"), partial)
    write_partial_marker(partial, binding)
    assert partial_offset(partial, binding) == 7
    partial.write_bytes(b"corrupt")
    assert partial_offset(partial, binding) == 0


@pytest.mark.parametrize("status", [404, 410])
def test_unavailable_photo_has_specific_failure_category(tmp_path: Path, status):
    from photointel.services.discovery import failure_category

    class MissingResponse:
        status_code = status

        def close(self):
            pass

    photo = SimpleNamespace(download=lambda *args, **kwargs: MissingResponse())
    version = SimpleNamespace(size=1, checksum="opaque", url="not-logged")
    adapter = ICloudAdapter(Settings(max_download_bytes=1024))
    adapter.client = SimpleNamespace(session=object())
    with pytest.raises(AppError) as caught:
        adapter.download(photo, version, tmp_path / "unavailable.image")
    assert caught.value.code == "ICLOUD_ASSET_UNAVAILABLE"
    assert failure_category(caught.value.code) == "remote_asset_unavailable"


@pytest.mark.parametrize("exception_name", ["ConnectTimeout", "ConnectionError"])
def test_transient_network_failure_does_not_request_reauthentication(exception_name):
    from photointel.services.discovery import failure_category

    code, _ = classify_icloud_failure(exception_name)
    assert failure_category(code) == "transient_network_error"



def test_icloud_representation_falls_back_only_to_allowed_non_original_sizes() -> None:
    from pyicloud_ipd.version_size import AssetVersionSize

    medium, thumb, original = (
        AssetVersionSize.MEDIUM,
        AssetVersionSize.THUMB,
        AssetVersionSize.ORIGINAL,
    )
    thumb_resource = SimpleNamespace(size=95000)
    medium_resource = SimpleNamespace(size=180000)
    original_resource = SimpleNamespace(size=9000000)
    settings = Settings(
        _env_file=None, download_representation="medium",
        allow_original_fallback=False,
    )
    adapter = ICloudAdapter(settings)
    assert adapter.representation(SimpleNamespace(versions={thumb: thumb_resource})) is thumb_resource
    assert adapter.representation(SimpleNamespace(versions={
        medium: medium_resource, thumb: thumb_resource,
    })) is medium_resource
    assert adapter.representation(SimpleNamespace(versions={original: original_resource})) is None
    thumbnail_adapter = ICloudAdapter(settings.model_copy(update={
        "download_representation": "thumb"
    }))
    assert thumbnail_adapter.representation(SimpleNamespace(
        versions={medium: medium_resource}
    )) is medium_resource
    approved = ICloudAdapter(settings.model_copy(update={
        "allow_original_fallback": True
    }))
    assert approved.representation(SimpleNamespace(
        versions={original: original_resource}
    )) is original_resource
